const listTaskCoordination = `-- name: ListTaskCoordination :many
SELECT t.id AS task_id,
       (SELECT count(*) FROM task_dependencies d JOIN tasks dt ON dt.id = d.depends_on_id
         WHERE d.task_id = t.id AND dt.status NOT IN ('done', 'cancelled'))::int AS open_dependencies,
       (SELECT count(*) FROM task_dependencies d WHERE d.task_id = t.id)::int AS dependencies_total,
       (SELECT count(*) FROM tasks c WHERE c.parent_id = t.id)::int AS children_total,
       (SELECT count(*) FROM tasks c WHERE c.parent_id = t.id AND c.status NOT IN ('done', 'cancelled'))::int AS children_open
FROM tasks t
WHERE t.company_id = $1 AND t.id = ANY($2::uuid[])
`

type ListTaskCoordinationParams struct {
	CompanyID uuid.UUID
	Ids       []uuid.UUID
}

type ListTaskCoordinationRow struct {
	TaskID            uuid.UUID
	OpenDependencies  int32
	DependenciesTotal int32
	ChildrenTotal     int32
	ChildrenOpen      int32
}

// Contadores derivados de várias tasks de uma vez: dependências abertas e filhos.
func (q *Queries) ListTaskCoordination(ctx context.Context, arg ListTaskCoordinationParams) ([]ListTaskCoordinationRow, error) {
	rows, err := q.db.Query(ctx, listTaskCoordination, arg.CompanyID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTaskCoordinationRow{}
	for rows.Next() {
		var i ListTaskCoordinationRow
		if err := rows.Scan(
			&i.TaskID,
			&i.OpenDependencies,
			&i.DependenciesTotal,
			&i.ChildrenTotal,
			&i.ChildrenOpen,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

