const listTaskSubtree = `-- name: ListTaskSubtree :many
WITH RECURSIVE down(id, depth) AS (
    SELECT t.id, 0 FROM tasks t WHERE t.id = $1 AND t.company_id = $2
    UNION ALL
    SELECT t.id, down.depth + 1 FROM tasks t JOIN down ON t.parent_id = down.id WHERE down.depth < 64
)
SELECT t.id, t.status, t.persona_id, down.depth::int AS depth FROM down JOIN tasks t ON t.id = down.id ORDER BY down.depth, t.number
`

type ListTaskSubtreeParams struct {
	RootID    uuid.UUID
	CompanyID uuid.UUID
}

type ListTaskSubtreeRow struct {
	ID        uuid.UUID
	Status    string
	PersonaID *uuid.UUID
	Depth     int32
}

// @root_id e todos os descendentes (a raiz tem profundidade 0).
func (q *Queries) ListTaskSubtree(ctx context.Context, arg ListTaskSubtreeParams) ([]ListTaskSubtreeRow, error) {
	rows, err := q.db.Query(ctx, listTaskSubtree, arg.RootID, arg.CompanyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTaskSubtreeRow{}
	for rows.Next() {
		var i ListTaskSubtreeRow
		if err := rows.Scan(
			&i.ID,
			&i.Status,
			&i.PersonaID,
			&i.Depth,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockTaskDependencies = `-- name: LockTaskDependencies :exec
SELECT pg_advisory_xact_lock(hashtextextended('task_dependencies:' || ($1::uuid)::text, 0))
`

// Serializa a escrita do grafo de dependências da empresa (a mesma chave que o trigger usa).
func (q *Queries) LockTaskDependencies(ctx context.Context, companyID uuid.UUID) error {
	_, err := q.db.Exec(ctx, lockTaskDependencies, companyID)
	return err
}

