const lockTaskHoldsShared = `-- name: LockTaskHoldsShared :exec

SELECT pg_advisory_xact_lock_shared(hashtextextended('task_hold:' || ($1::uuid)::text, 0))
`

// ---------- pausa ----------
// O checkout de run segura este lock compartilhado; pausar e retomar o seguram exclusivo, então uma run não abre
// no meio de uma pausa em andamento. Sempre o primeiro lock da transação (antes de qualquer task).
func (q *Queries) LockTaskHoldsShared(ctx context.Context, companyID uuid.UUID) error {
	_, err := q.db.Exec(ctx, lockTaskHoldsShared, companyID)
	return err
}

